a, b, c = map(int, input().split())

# Perform division manually
decimal_digits = []
remainder = a % b

if remainder == 0:
    # No decimal part, digit c won't appear (except if c=0, which appears at every position)
    if c == 0:
        print(1)  # 0 appears at position 1 if there's no decimal part
    else:
        print(-1)
else:
    # Track seen remainders to detect infinite loops
    seen_remainders = set()
    position = -1
    pos = 1
    while remainder != 0 and position == -1:
        if remainder in seen_remainders:
            # Infinite loop without finding c
            break
        seen_remainders.add(remainder)

        remainder *= 10
        digit = remainder // b
        remainder = remainder % b

        if digit == c:
            position = pos
        pos += 1

    # After loop, check if we need to consider remainder == 0 case
    if remainder == 0 and position == -1:
        # All digits are 0 from this point on
        if c == 0:
            print(pos)
        else:
            print(-1)
    else:
        print(position)
"}

