{"code": "
a, m = map(int, input().split())

# If a is already divisible by m, production stops immediately
if a % m == 0:
    print("Yes")
else:
    # We keep adding a%m each day and check if we ever become divisible by m
    current = a
    # Simulate up to m days (since there are only m possible remainders)
    for _ in range(m):
        current += a % m
        if current % m == 0:
            print("Yes")
            break
    else:
        print("No")
"}

