def solve():
    n = int(input())
    heights = list(map(int, input().split()))

    # For each hill, find the set of hills it can see clockwise
    can_see_clockwise = [0] * n
    for i in range(n):
        j = i
        while j != i:
            j = (j + 1) % n
            if heights[j] <= heights[i]:
                can_see_clockwise[i] += 1
            else:
                break

    # Count pairs
    count = 0
    for i in range(n):
        count += can_see_clockwise[i]

