# Compute z after n seconds starting from 1
if k == 1:
    z = 1 + b * n
else:
    # z = k^n * 1 + b * (k^(n-1) + k^(n-2) + ... + 1)
    # = k^n + b * (k^n - 1) / (k - 1)
    power_n = pow(k, n, (k - 1) * (10**18))  # Use modulo to prevent overflow
    z = (power_n * k + b * (power_n - 1)) // (k - 1)

# Find minimum seconds m needed to reach at least z starting from t
if t >= z:
    print(0)
elif k == 1:
    # Linear growth: x = t + b * m
    print((z - t + b - 1) // b)
else:
    # We need: k^m * t + b * (k^m - 1) / (k - 1) >= z
    # This simplifies to: k^m * (t * (k - 1) + b) >= z * (k - 1) + b
    numerator = z * (k - 1) + b
    denominator = t * (k - 1) + b
    if denominator == 0:
