        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            # Calculate k^mid without overflow
            power_mid = pow(k, mid, 10**18)  # Use modulo to keep numbers small
            if power_mid * denominator >= numerator:
                right = mid
            else:
                left = mid + 1
        print(left)
