    if len(first_points) > len(second_points):
        # Check if second_points is a prefix of first_points
        if first_points[:len(second_points)] == second_points:
            print("first")
        else:
            # Compare element by element
            for i in range(min(len(first_points), len(second_points))):
                if first_points[i] > second_points[i]:
                    print("first")
                    break
            else:
                # All equal up to min length
                if len(first_points) > len(second_points):
                    print("first")
