def min_squares_to_disconnect(n, m, grid):
    # Find all painted squares
    painted = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                painted.append((i, j))

    # If there's only one painted square, it's already disconnected
    if len(painted) == 1:
        return -1

    # Try all painted squares as the starting point
    min_cut = float('inf')

    for start in painted:
        # BFS from start to find distances
        visited = [[False] * m for _ in range(n)]
        queue = [(start[0], start[1], 0)]
        visited[start[0]][start[1]] = True

        while queue:
            i, j, dist = queue.pop(0)
            visited[i][j] = True

            # Check if we've reached a boundary (where a square is not painted)
            if i == 0 or i == n-1 or j == 0 or j == m-1:
                # If we reached the boundary, this might be a candidate for a cut
                # But we need to verify if there's still a path through the interior
                cut_count = dist

                # Check if there's still a path through the interior squares
                has_interior_path = False

                # BFS from boundary to check interior connectivity
                interior_visited = [[False] * m for _ in range(n)]
                interior_queue = [(i, j, 0)]
                interior_visited[i][j] = True

                while interior_queue:
                    x, y, _ = interior_queue.pop(0)
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if not interior_visited[nx][ny] and grid[nx][ny] == '#':
                                interior_visited[nx][ny] = True
                                interior_queue.append((nx, ny, 0))

                # Check if all interior painted squares are connected
                if all(interior_visited[i][j] for i in range(n) for j in range(m) if grid[i][j] == '#'):
                    min_cut = min(min_cut, cut_count)

            # Explore neighbors
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + dx, j + dy
                if 0 <= ni < n and 0 <= nj < m:
                    if not visited[ni][nj] and grid[ni][nj] == '#':
                        visited[ni][nj] = True
                        queue.append((ni, nj, dist + 1))

    return min_cut if min_cut != float('inf') else -1

n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(input().strip())

result = min_squares_to_disconnect(n, m, grid)
print(result if result != float('inf') else -1)
