        for end in painted:
            if start == end:
                continue

            # Find the minimum path from start to end that goes through the fewest painted squares
            # This path will be our cut (the squares on this path are the ones we need to delete)

            # BFS to find minimum distance from start to end
            # We'll track distances from start
            visited = [[False] * m for _ in range(n)]
            queue = [(start[0], start[1], 0)]
            visited[start[0]][start[1]] = True
            distances = [[-1] * m for _ in range(n)]
            distances[start[0]][start[1]] = 0

            while queue:
                i, j, dist = queue.pop(0)

                # If we reached the end, this is our minimum path length
                if (i, j) == end:
                    cut_count = dist + 1  # +1 because we include both start and end
                    min_cut = min(min_cut, cut_count)
