def find_kth_string(n, k):
    # Find the position of the first 'b'
    first_b = 1
    count = 0

    # Iterate to find the first 'b' position
    for first_b in range(1, n + 1):
        count = n - first_b + 1  # n - first_b + 1 = n - (first_b - 1)
        if count < k:
            k -= count
        else:
            break

    # Now find the position of the second 'b'
    second_b = first_b + 1
    count = n - first_b

    # Iterate to find the second 'b' position
    for second_b in range(first_b + 1, n + 1):
        if count < k:
            k -= count
        else:
            break

    # Build the string
    result = ['a'] * n
