def solve():
    n, m = map(int, input().split())

    # Build adjacency lists
    adj = [[] for _ in range(n + 1)]  # 1-indexed
    for _ in range(m):
        v, u, c = input().split()
        adj[int(v)].append((int(u), c))

    # Game states: dp[i][j] = 1 if current player (Max) can win with Max at i and Lucas at j
    # 0 means current player loses
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Process in reverse topological order
    # We'll use memoization with current positions and last character
    # But since we only care about whether a player can win, we can simplify

    # First, for each position, find all reachable positions in one move from that position
    from collections import defaultdict
    reachable = [defaultdict(set) for _ in range(n + 1)]

    # For each vertex, precompute all direct edges
    for v in range(1, n + 1):
        for u, c in adj[v]:
            reachable[v][u].add(c)

    # Process in reverse topological order
    # We need to find topological order

    # Build reverse graph for topological sort
    rev_adj = [[] for _ in range(n + 1)]
    for v in range(1, n + 1):
        for u, _ in adj[v]:
            rev_adj[u].append(v)

    # Perform topological sort on the reverse graph
    topo_order = []
    visited = [False] * (n + 1)

    def dfs(u):
        visited[u] = True
        for v in rev_adj[u]:
            if not visited[v]:
                dfs(v)
        topo_order.append(u)

    for v in range(1, n + 1):
        if not visited[v]:
            dfs(v)

    # Process in reverse topological order
    # dp[i][j] = 1 if current player can win with Max at i and Lucas at j
    # 0 means current player loses

    # For each pair (i, j), we need to determine if current player can win
    # This is a classic game theory problem where:
    # - If current player has a move to a state where the opponent loses, they win
    # - Otherwise they lose

    for i in reversed(topo_order):
        for j in range(1, n + 1):
            # Check if current player (Max) can win from (i, j)
            # Max's turn: look at edges from i
            max_win = False
            for next_pos, c in adj[i]:
                # For each possible move by Max, check all valid moves by Lucas
                for lucas_pos, l_char in adj[j]:
                    if l_char >= c:
                        # Lucas's turn: need to check if Lucas can win from (next_pos, lucas_pos)
                        # If dp[next_pos][lucas_pos] == 0, it means Lucas loses, so Max wins
                        if dp[next_pos][lucas_pos] == 0:
                            max_win = True
                            break
                if max_win:
                    break

            dp[i][j] = 1 if max_win else 0

    # Output the result
    for i in range(1, n + 1):
        result = []
        for j in range(1, n + 1):
            if dp[i][j] == 1:
                result.append('A')
            else:
                result.append('B')
        print(''.join(result))

