        candies_by_type = {}  # type -> list of f_i
        for _ in range(n):
            a = int(next(data))
            f = int(next(data))
            if a not in candies_by_type:
                candies_by_type[a] = []
            candies_by_type[a].append(f)

        # Sort each type's candies by f_i (1 first, then 0)
        for a in candies_by_type:
            candies_by_type[a].sort(reverse=True)

        # Get count of types with at least 2 candies (can pick 2 from them)
        count_2_plus = 0
        max_f_2 = 0

        for a in candies_by_type:
            if len(candies_by_type[a]) >= 2:
                count_2_plus += 1
                # max f_1 we get from picking 2 from this type
                # if both are 1, we get 2 f=1 candies
                # but we only pick 2 candies, so max 2
                if candies_by_type[a][0] == 1:
                    if candies_by_type[a][1] == 1:
                        max_f_2 += 2
                    else:
                        max_f_2 += 1
                else:
                    max_f_2 += 0
            else:
                # for types with only 1 candy
                if candies_by_type[a][0] == 1:
                    max_f_1_case1 = 1
                else:
                    max_f_1_case1 = 0

        # Case 1: pick one type with count 2 and one type with count 1
        # We need to choose the best type with 2+ candies
        # And also the best type with 1 candy
        # 
        # Case 1A: pick count 2 from a type with 2+ candies
        # and pick count 1 from a type with 1 candy
        # We can only do this if both types exist

        if count_2_plus > 0:
            # Best type with 2+ candies for f=1
            max_f_2_type = 0
            for a in candies_by_type:
                if len(candies_by_type[a]) >= 2:
                    if candies_by_type[a][0] == 1:
                        if candies_by_type[a][1] == 1:
                            f_total = 2
                        else:
                            f_total = 1
                    else:
                        f_total = 0
                    if f_total > max_f_2_type:
                        max_f_2_type = f_total

            # Best type with 1 candy for f=1
            max_f_1_type = 0
            for a in candies_by_type:
                if len(candies_by_type[a]) == 1:
                    if candies_by_type[a][0] == 1:
                        max_f_1_type = 1
                    else:
                        max_f_1_type = 0

            # Case 1: max total = 3, max f_1 = max_f_2_type + max_f_1_type
            case1_total = 3
            case1_f1 = max_f_2_type + max_f_1_type
        else:
            # No type with 2+ candies
            case1_total = 0
            case1_f1 = 0

        # Case 2: pick one type with count 2 (no other types)
        # max total = 2, max f_1 = max_f_2
        case2_total = 2
        case2_f1 = max_f_2

        # Case 3: pick one type with count 1 (no other types)
        # max total = 1, max f_1 = max_f_1_type
        case3_total = 1
        case3_f1 = max_f_1_type

        # Choose the best total
        best_total = 0
        best_f1 = 0

        # For max total = 3, we need both case1_total = 3 and case1_f1
        if case1_total == 3:
            if case1_total > best_total or (case1_total == best_total and case1_f1 > best_f1):
                best_total = case1_total
                best_f1 = case1_f1

        # For max total = 2, we need case2_total = 2
        if case2_total > best_total or (case2_total == best_total and case2_f1 > best_f1):
            best_total = case2_total
            best_f1 = case2_f1

        # For max total = 1, we need case3_total = 1
        if case3_total > best_total or (case3_total == best_total and case3_f1 > best_f1):
            best_total = case3_total
            best_f1 = case3_f1

        results.append(f"{best_total} {best_f1}")

    sys.stdout.write("\n".join(results))

solve()
