def can_reach(n, k, l, depths):
    """Check if Koa can reach the island"""
    # p = [0, 1, ..., k-1, k, k-1, ..., 1]
    max_time = 2 * k  # We only need to check the first cycle

    # BFS: (position, time) -> boolean
    from collections import deque

    visited = [[False] * (2 * k + 1) for _ in range(n + 2)]
    queue = deque([(0, 0)])  # (position, time)
    visited[0][0] = True

    while queue:
        pos, time = queue.popleft()

        # If we reached the island
        if pos == n + 1:
            return True

        # If we haven't reached the island, check if we can stay or swim
        if pos > 0:
            # We're at position pos > 0, we need to check if we can stay here
            # But wait, if pos > 0 and we're at time, we need to check if we can be here
            if time % (2 * k) >= 0:
                # Check depth constraint
                if d[pos] + p[time % (2 * k)] <= l:
                    # We can stay here
                    if not visited[pos][time % (2 * k)]:
                        visited[pos][time % (2 * k)] = True
                        queue.append((pos, time + 1))

        # Try swimming to pos+1
        if pos < n:
            new_time = time + 1
            if not visited[pos + 1][new_time % (2 * k)]:
                visited[pos + 1][new_time % (2 * k)] = True
                queue.append((pos + 1, new_time))

    return False

