def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    dist = [float('inf')] * n
    dist[0] = 0

    # Priority queue: (cost, node)
    pq = [(0, 0)]

    while pq:
        cost, u = heapq.heappop(pq)

        if cost > dist[u]:
            continue

        # Move to u + 1 (node u+1, 0-indexed) with cost 1
        if u + 1 < n:
            if dist[u + 1] > cost + 1:
                dist[u + 1] = cost + 1
                heapq.heappush(pq, (dist[u + 1], u + 1))

        # Move to u - 1 (node u-1, 0-indexed) with cost 1
        if u - 1 >= 0:
            if dist[u - 1] > cost + 1:
                dist[u - 1] = cost + 1
                heapq.heappush(pq, (dist[u - 1], u - 1))

        # Use shortcut from u + 1 (1-indexed) to a[u + 1] (1-indexed)
        if u + 1 < n:
            shortcut_to = a[u + 1] - 1
            if dist[shortcut_to] > cost + 1:
