                # Keep the command
                if commands[i] == 'F':
                    if facing == 0:
                        new_pos = dp[i][j][facing] + 1
                    else:
                        new_pos = dp[i][j][facing] - 1
                    if new_pos > dp[i+1][j][facing]:
                        dp[i+1][j][facing] = new_pos
                elif commands[i] == 'T':
                    new_facing = 1 - facing
                    if dp[i+1][j][new_facing] < dp[i][j][facing]:
                        dp[i+1][j][new_facing] = dp[i][j][facing]

