import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    ptr = 0
    q = int(data[ptr])
    ptr += 1

    for _ in range(q):
        n = int(data[ptr])
        ptr += 1

        # costs for previous a, a+1, a+2
        prev_costs = [0, 0, 0]

        for i in range(n):
            a = int(data[ptr])
            b = int(data[ptr + 1])
            ptr += 2

            if i == 0:
                # First position, we can set to a, a+1, or a+2
                prev_costs[0] = 0  # a
                prev_costs[1] = b   # a+1
                prev_costs[2] = 2 * b  # a+2
            else:
                curr_costs = [0, 0, 0]

                # Previous position had height a_prev, a_prev+1, or a_prev+2
                # For each possible current height (a, a+1, a+2)
                for curr_h in range(3):
                    # Find minimum valid previous cost
                    min_prev_cost = float('inf')
                    for prev_h in range(3):
                        # Check if previous height is different from current height
                        if a_prev + prev_h != a + curr_h:
                            if prev_costs[prev_h] < min_prev_cost:
                                min_prev_cost = prev_costs[prev_h]

                    # Cost to set to current height a + curr_h
                    if curr_h == 0:
                        curr_cost = 0
                    elif curr_h == 1:
                        curr_cost = b
                    else:
                        curr_cost = 2 * b

                    curr_costs[curr_h] = min_prev_cost + curr_cost

                prev_costs = curr_costs

        result = min(prev_costs)
        print(result)

if __name__ == "__main__":
    solve()
