def find_proper_divisors(n):
    """Return list of proper divisors of n where 1 < d < n"""
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            if i < n:
                divisors.add(i)
            if (n // i) < n and (n // i) != i:
                divisors.add(n // i)
    return sorted(divisors)

def solve():
    n = int(input().strip())

    # Check if n is prime
    divisors = find_proper_divisors(n)
    if not divisors:
        print("NO")
        return

    # Check if n is a prime power
    prime_factors = set()
    temp = n
    for i in range(2, int(temp**0.5) + 1):
        if temp % i == 0:
            prime_factors.add(i)
            while temp % i == 0:
                temp //= i
    if temp > 1:
        prime_factors.add(temp)

    if len(prime_factors) == 1:
        print("NO")
        return

    print("YES")
    print(len(divisors))

    # Construct sequence
    a = {d: d-1 for d in divisors}  # Start with max possible a_i
    # Calculate total sum
    total = sum(a[d] * (n // d) for d in divisors)

    # Greedily decrease a_i where needed
    # Find divisors in order of decreasing n/d
    sorted_divisors = sorted(divisors, key=lambda d: -(n // d))

    for d in sorted_divisors:
        if total > n - 1:
            # Need to reduce total by some amount
            amount_to_reduce = total - (n - 1)
            a[d] = (a[d] - amount_to_reduce) if amount_to_reduce < a[d] else 0
            total -= amount_to_reduce
        elif total < n - 1:
            # Need to increase total
            amount_to_increase = (n - 1) - total
            a[d] = a[d] + amount_to_increase
            total += amount_to_increase

    # Output the sequence
    for d, a_i in a.items():
        print(a_i, d)

solve()
