    # Check if it's a straight line
    straight = True
    start_col = None
    prev = None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                if start_col is None:
                    start_col = j
                    prev = (i, j)
                else:
                    # Check if it's a straight line
                    if i != prev[0] and j != prev[1]:
                        straight = False
                        break
                    if i == prev[0]:
                        # Same row
                        if j == prev[1] + 1:
                            prev = (i, j)
                        else:
                            straight = False
                            break
                    else:
                        # Same column
                        if i == prev[0] + 1:
                            prev = (i, j)
                        else:
                            straight = False
                            break
        if not straight:
