def count_painted_cells(n, segments):
    # Dictionary to store covered cells
    covered = {}

    for seg in segments:
        x1, y1, x2, y2 = seg

        # Check if segment is horizontal (fixed y)
        if y1 == y2:
            # Horizontal segment at row y1
            y = y1
            x_min = min(x1, x2)
            x_max = max(x1, x2)

