import sys
from sys import stdin

def solve():
    data = stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Initialize DSU
    parent = list(range(n))
    rank = [1] * n

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu == pv:
            return
        if rank[pu] < rank[pv]:
            parent[pu] = pv
        else:
            parent[pv] = pu
            if rank[pu] == rank[pv]:
                rank[pu] += 1

    # For each bit, maintain a sorted list of positions that have this bit set
    bit_positions = [[] for _ in range(31)]
    for i in range(n):
        if a[i] > 0:
            for b in range(31):
                if a[i] & (1 << b):
                    bit_positions[b].append(i)

    # Process from left to right
    for i in range(n):
        if a[i] == 0:
            # This position can't reach anyone
            continue

        # Get all bits set in a[i]
        bits_set = []
        for b in range(31):
            if a[i] & (1 << b):
                bits_set.append(b)

        # For each bit, union i with all positions j > i in this bit's list
        for b in bits_set:
            j = 0
            while j < len(bit_positions[b]):
                pos = bit_positions[b][j]
                if pos > i:
                    union(i, pos)
                    # Remove pos from the list
                    bit_positions[b][j] = bit_positions[b][-1]
                    bit_positions[b].pop()
                else:
                    break

    # Read queries and answer
    out = []
    for _ in range(q):
        x = int(next(it)) - 1
        y = int(next(it)) - 1
        if find(x) == find(y):
            out.append("Shi")
        else:
            out.append("Fou")

