def solve() -> None:
    n, t = map(int, input().split())
    balls = []

    for _ in range(n):
        x, v, m = map(int, input().split())
        balls.append((x, v, m))

    # Calculate final positions without considering collisions
    final_positions = [(x + v * t) for x, v, m in balls]

    # Find collision times
    collisions = []

    for i in range(n):
        for j in range(i + 1, n):
            xi, vi, mi = balls[i]
            xj, vj, mj = balls[j]

            if vi != vj:
                if vi > vj:
                    time_to_collision = (xj - xi) / (vi - vj)
                else:
                    time_to_collision = (xi - xj) / (vj - vi)

                if time_to_collision <= t:
                    collisions.append((i, j, time_to_collision, xi, xj, vi, vj))

    # Sort collisions by time
    collisions.sort()

    # Process collisions (swap velocities)
    # Actually, for elastic collisions, we can just swap velocities
    for i, j, t_col, xi, xj, vi, vj in collisions:
        # Swap velocities
        balls[i] = (xi + vi * t_col, vj, balls[i][2])
        balls[j] = (xj + vj * t_col, vi, balls[j][2])

    # Update remaining time for all balls
    for i in range(n):
        xi, vi, mi = balls[i]
        final_positions[i] = xi + vi * (t - t_col) if collisions else xi + vi * t

    for pos in final_positions:
        print(f"{pos:.10f}")

