def can_reach(target, k):

    # Try to decompose target into sum of powers of k
    # Each power can be used at most once

    while target > 0:
        # Try to subtract the largest power of k <= target
        power = 1
        while power * k <= target:
            power *= k

        # Check if we can use this power
        if power > target:
            return False

        # Use this power
        target -= power

    return True


