def move(n, v, direction):
    """Move from vertex v in the given direction."""
    if direction == 'L':
        return 2 * v
    elif direction == 'R':
        return 2 * v + 1
    elif direction == 'U':
        return (v - 1) // 2
    else:
        raise ValueError(f"Invalid direction: {direction}")

def solve(n, queries):
    result = []
    for ui, si in queries:
        v = ui
        for c in si:
            if c == 'L':
                next_v = 2 * v
            elif c == 'R':
                next_v = 2 * v + 1
            elif c == 'U':
                next_v = (v - 1) // 2
            else:
                next_v = v  # Skip invalid direction

            # Check if next_v is within bounds
            if 1 <= next_v <= n:
                v = next_v
        result.append(v)
    return result

