def solve():
    n = int(input())
    nums = list(map(int, input().split()))

    # Count frequencies
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Create a list of all positions (i, j)
    positions = []
    for i in range(n):
        for j in range(n):
            positions.append((i, j))

    # Create a grid to store the matrix
    grid = [[None for _ in range(n)] for _ in range(n)]

    # Try to fill the matrix
    for i in range(n):
        for j in range(n):
            # If position (i, j) is already filled, skip
            if grid[i][j] is not None:
                continue

            # Determine the symmetry group size
            if i == n - i - 1 and j == n - j - 1:
                # Center position if n is odd
                size = 1
            elif i == n - i - 1 or j == n - j - 1:
                # Edge position (not center)
                size = 2
            else:
                # Corner position
                size = 4

            # Find a number with the correct frequency
            found = False
            for num, count in freq.items():
                if count >= size:
                    # Place this number in the symmetry group
                    for x, y in [(i, j), (n - i - 1, j), (i, n - j - 1), (n - i - 1, n - j - 1)]:
                        grid[x][y] = num
                    # Update frequency
                    freq[num] -= size
                    found = True
                    break

            if not found:
                print("NO")
                return

    # Print result
    print("YES")
    for row in grid:
        print(' '.join(map(str, row)))

