import sys

def get_position(a, d, total_distance):
    # Side length
    side = a

    # Check which side we're on
    if total_distance <= side:
        # Right along bottom side (0,0) -> (a,0)
        return (total_distance, 0.0)
    elif total_distance <= 2 * side:
        # Up along right side (a,0) -> (a,a)
        remaining = total_distance - side
        return (a, remaining)
