import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    damage = int(next(it))
    increase_per_second = int(next(it))
    max_health = int(next(it))

    enemies = []
    for _ in range(n):
        max_h = int(next(it))
        initial_h = int(next(it))
        regen_r = int(next(it))
        enemies.append((max_h, initial_h, regen_r))

    # Map: enemy -> (time, health)
    updates = {}
    for _ in range(m):
        t = int(next(it))
        j = int(next(it)) - 1  # 0-indexed
        h = int(next(it))
        updates[j] = (t, h)

    # For each enemy, find all times t where they die
    times = [[] for _ in range(n)]

    for j in range(n):
        max_h, initial_h, regen_r = enemies[j]

        # Function to compute health at time t
        def health(t):
            # Apply updates
            for update_t, update_h in updates.get(j, []):
                if t < update_t:
                    return min(initial_h + regen_r * t, max_h)
                elif t == update_t:
                    return update_h
                else:
                    return min(update_h + regen_r * (t - update_t), max_h)
            return min(initial_h + regen_r * t, max_h)

        # Find all times t where health <= damage
        times_j = []
        t = 0
        while True:
            current_h = health(t)
            if current_h <= damage:
                times_j.append(t)
            # Check if health can ever exceed damage
            # If we've seen health > damage, it can't decrease
            if current_h > damage:
                break
            # Check if health can ever reach damage
            # If we've seen health = damage, we have found all times
            if current_h == damage:
                break
            t += 1

        times[j] = times_j

    # Count number of enemies dead at each time
    count = {}  # time -> number of enemies

    for j in range(n):
        for t in times[j]:
            count[t] = count.get(t, 0) + 1

    if not count:
        # No enemy ever dies, so max time is infinity
        print(-1)
        return

    # Find the time that maximizes gold
    # Gold at time t: count[t] * (damage + increase_per_second * t)
    # We need to find max over t in count

    max_gold = -1
    best_t = -1

    for t in count:
        gold = count[t] * (damage + increase_per_second * t)
        if gold > max_gold:
            max_gold = gold
            best_t = t

    print(max_gold)

if __name__ == '__main__':
    solve()
