def solve_test_case(n, k, l, d):
    """Check if Koa can get from shore to island"""
    # First check: can she be at any position at all?
    for i in range(n):
        if d[i] > l:
            return "No"

    # For each position, determine the times (mod 2k) when it's valid
    valid_times = [[] for _ in range(n + 2)]  # positions 0 to n+1

    for position in range(n + 2):
        if position == 0 or position == n + 1:
            valid_times[position] = [i for i in range(2 * k)]
        else:
            a = l - d[position - 1]
            if a < 0:
                return "No"

            valid = []
            for t_mod in range(2 * k):
                if t_mod < k:
                    tide = t_mod
                else:
                    tide = 2 * k - 1 - t_mod
                if tide <= a:
                    valid.append(t_mod)
            valid_times[position] = valid

    # Use BFS to find path
    from collections import deque

    # State: (position, time_mod_2k)
    visited = [[False] * (2 * k) for _ in range(n + 2)]

    # Start at position 0 at time 0
    if not visited[0][0]:
        visited[0][0] = True
        queue = deque([(0, 0)])

    while queue:
        position, time_mod_2k = queue.popleft()

        # If we reached the island
        if position == n + 1:
            return "Yes"

        # Move to next position if possible
        next_position = position + 1
        next_time = (time_mod_2k + 1) % (2 * k)

        # Check if next_position is valid at next_time
        if next_position <= n + 1:
            if not visited[next_position][next_time]:
                if next_time in valid_times[next_position]:
                    visited[next_position][next_time] = True
                    queue.append((next_position, next_time))

        # Stay at current position, next time
        next_time = (time_mod_2k + 1) % (2 * k)
        if not visited[position][next_time]:
            if next_time in valid_times[position]:
                visited[position][next_time] = True
                queue.append((position, next_time))

    return "No"


