def seconds(time_str):
    h, m, s = map(int, time_str.split(':'))
    return h * 3600 + m * 60 + s

def main():
    import sys
    input = sys.stdin.read().splitlines()
    if not input:
        return

    n, M, T = map(int, input[0].split())
    times = [seconds(input[i+1]) for i in range(n)]

    # Greedy: Maximize users by assigning different users to non-overlapping intervals
    user_ids = []
    max_users = 0

    for i in range(n):
        s = times[i]
        e = s + T - 1

        # Check if we can assign a new user (no overlap with any previous user's interval)
        can_assign = True
        for j in range(len(user_ids)):
            if times[j] <= e and times[j] + T - 1 >= s:
                can_assign = False
                break

        if can_assign:
            user_ids.append(len(user_ids) + 1)
        else:
            # Try to find an existing user whose interval overlaps with this one
            found = False
            for j in range(len(user_ids)):
                if times[j] <= e and times[j] + T - 1 >= s:
                    user_ids.append(j + 1)  # Reuse existing user
                    found = True
                    break

            if not found:
                # No user can be assigned without exceeding max users
                print("No solution")
                return

        max_users = max(max_users, len(user_ids))

    print(max_users)
    for user_id in user_ids:
        print(user_id)

