from collections import Counter

def solve():
    data = input().split()
    n = int(data[0])
    numbers = list(map(int, data[1:1+n*n]))

    freq = Counter(numbers)

    if n % 2 == 0:
        half = n // 2
        independent = half * half
    else:
        half = (n + 1) // 2
        independent = half * half

    result = [[0] * n for _ in range(n)]

    for i in range(half):
        for j in range(half):
            if i <= n/2 - 1 and j <= n/2 - 1:
                # Try to find a number for this position
                found = False
                for num, count in freq.items():
                    # Check if we can place this number
                    # Count how many cells this independent position determines
                    # and whether we have enough occurrences
                    occupied = 0

                    # Check if we have enough of this number
                    if count < 2:
                        # Only one occurrence, can't place this number here
                        continue

                    # Place the number in all symmetric cells
                    for sym_i in range(n):
                        for sym_j in range(n):
                            if (i, j) == (sym_i, sym_j) or 
                               (i, j) == (n-1-sym_i, j) or 
                               (i, j) == (i, n-1-sym_j) or 
                               (i, j) == (n-1-sym_i, n-1-sym_j):
                                if result[sym_i][sym_j] == 0:
                                    result[sym_i][sym_j] = num
                                    occupied += 1

                    if occupied <= count:
                        # We can place this number
                        freq[num] -= occupied
                        if freq[num] == 0:
                            del freq[num]
                        found = True
                        break

                if not found:
                    print("NO")
                    return

    print("YES")
    for row in result:
        print(' '.join(map(str, row)))

solve()
