for l, r, idx in segments:
    # Find which points are in [l, r]
    left = 0
    right = n
    while left < right:
        mid = (left + right) // 2
        if points[mid] < l:
            left = mid + 1
        else:
            right = mid
    start = left
    right = n
    while left < right:
        mid = (left + right) // 2
        if points[mid] > r:
            right = mid
        else:
            left = mid + 1
    end = left - 1

    # Count coverage
    for i in range(start, end + 1):
        coverage[i] += 1

