# If coverage is odd, we need one extra color
# Let's color points with higher coverage blue
colors = [0] * n
for i in range(n):
    if coverage[i] % 2 == 1:
        colors[i] = 1  # Blue for odd coverage

# Check if this works
valid = True
for l, r, idx in segments:
