def solve():
    n = int(input())
    events = []
    for _ in range(n):
        parts = input().split()
        events.append((parts[0], int(parts[1])))

    # dp[i]: dictionary where key = memory stick capacity (-1 for none), value = max earnings
    dp = [{} for _ in range(n + 1)]
    dp[0][-1] = 0

    for day in range(n):
        event_type, x = events[day]
        dp[day + 1] = {}

        # Propagate from previous day
        for c in dp[day]:
            current_earnings = dp[day][c]

            if event_type == "win":
                # Option 1: keep the new stick (if we don't already have one)
                if c == -1:
                    dp[day + 1][x] = max(dp[day + 1].get(x, -1), current_earnings)
                # Option 2: don't keep it (we could also not keep it if we already have one)
                dp[day + 1][c] = max(dp[day + 1].get(c, -1), current_earnings)
            else:  # sell
                # If we have the stick, we sell it
                if c == x:
                    dp[day + 1][-1] = max(dp[day + 1].get(-1, -1), current_earnings + (1 << x))
                # If we don't have it, we don't change
                dp[day + 1][c] = max(dp[day + 1].get(c, -1), current_earnings)

    # Maximum earnings across all final states
    max_earnings = 0
    for c in dp[n]:
        if dp[n][c] > max_earnings:
            max_earnings = dp[n][c]

    print(max_earnings)

