    """Union by rank (height)."""
    px = find(parent, x)
    py = find(parent, y)
    if px != py:
        if rank[px] < rank[py]:
            parent[px] = py
        else:
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1


