from collections import defaultdict

def merge_segments(segments):
    # Group by coordinate
    groups = defaultdict(list)
    for x1, y1, x2, y2 in segments:
        if x1 == x2:  # vertical segment
            groups[x1].append((y1, y2))
        else:  # horizontal segment
            groups[y1].append((x1, x2))

    total = 0
    # Process horizontal segments (grouped by y)
    for y, segs in groups.items():
        # Sort segments by start x
        segs.sort()
        # Merge overlapping or touching segments
        merged = []
        for s in segs:
            if not merged:
                merged.append(s)
            else:
                last = merged[-1]
                if s[0] <= last[1] + 1:  # touching or overlapping
                    new_seg = (last[0], max(last[1], s[1]))
                    merged[-1] = new_seg
                else:
                    merged.append(s)
        # Count cells for this y-coordinate
        for x1, x2 in merged:
            total += x2 - x1 + 1

    # Process vertical segments (grouped by x)
    for x, segs in groups.items():
        # Sort segments by start y
        segs.sort()
        # Merge overlapping or touching segments
        merged = []
        for s in segs:
            if not merged:
                merged.append(s)
            else:
                last = merged[-1]
                if s[0] <= last[1] + 1:  # touching or overlapping
                    new_seg = (last[0], max(last[1], s[1]))
                    merged[-1] = new_seg
                else:
                    merged.append(s)
        # Count cells for this x-coordinate
        for y1, y2 in merged:
            total += y2 - y1 + 1

    return total

def main():
    n = int(input())
    segments = []
    for _ in range(n):
        x1, y1, x2, y2 = map(int, input().split())
        segments.append((x1, y1, x2, y2))

    print(merge_segments(segments))

