def has_hole(grid, n, m):
    visited = [[False] * m for _ in range(n)]

    # Flood fill from the outer boundary
    queue = []

    # Top row
    for j in range(m):
        if grid[0][j] == '#':
            visited[0][j] = True
            queue.append((0, j))

    # Bottom row
    for j in range(m):
        if grid[n-1][j] == '#':
            visited[n-1][j] = True
            queue.append((n-1, j))

    # Leftmost column
    for i in range(1, n-1):
        if grid[i][0] == '#':
            visited[i][0] = True
            queue.append((i, 0))

    # Rightmost column
    for i in range(1, n-1):
        if grid[i][m-1] == '#':
            visited[i][m-1] = True
            queue.append((i, m-1))

    # BFS flood fill
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while queue:
        i, j = queue.pop(0)
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m:
                if not visited[ni][nj] and grid[ni][nj] == '#':
                    visited[ni][nj] = True
                    queue.append((ni, nj))

    # Check if there's any unvisited painted square that is surrounded
    for i in range(1, n-1):
        for j in range(1, m-1):
