def solve():
    n = int(input())

    # Find all proper divisors of n (1 < d < n)
    divisors = []
    for d in range(2, n):
        if n % d == 0:
            divisors.append(d)

    if len(divisors) == 0:
        print("NO")
        return

    # Try to construct a solution using a simple greedy algorithm
    k = 0
    sum_so_far = 0.0

    # Use the largest divisor first (not 1 or n)
    for d in sorted(divisors, reverse=True):
        if 1 < d < n:
            k += 1
            sum_so_far += 1.0 / d
            if sum_so_far >= 1 - 1.0 / n:
                break

    if abs(sum_so_far - (1 - 1.0 / n)) < 1e-9:
        print("YES")
