from collections import Counter

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        pins = []
        for _ in range(n):
            pins.append(input().strip())

        # Count frequency of each PIN
        freq = Counter(pins)

        # If all are unique, no changes needed
        if all(v == 1 for v in freq.values()):
            print(0)
            for pin in pins:
                print(pin)
        else:
            # Need to make changes
            changes = 0
            new_pins = []

            # For each PIN, if there are duplicates, change digits
            for pin in pins:
                # If there are multiple copies, we need to change this one
                if freq[pin] > 1:
                    freq[pin] -= 1
                    changes += 1

                    # Change digits until it becomes unique
                    new_pin = list(pin)
                    modified = False

                    # Try changing each position
                    for i in range(4):
                        # Try changing to a different digit
                        for d in range(10):
                            if d != int(new_pin[i]):
                                new_pin[i] = str(d)
                                modified = True
                                break
                        if modified:
                            break

                    new_pins.append(''.join(new_pin))
                else:
                    new_pins.append(pin)

