def dot_product(a, b):
    """Calculate the dot product of vectors a and b"""
    return sum(x * y for x, y in zip(a, b))

def is_good(point_idx, points):
    """Check if point at index point_idx is good"""
    n = len(points)
    point_a = points[point_idx]

    # Try all pairs of points (b, c) where b != c and both != point_idx
    for b in range(n):
        if b == point_idx:
            continue
        for c in range(n):
            if c == point_idx or c == b:
                continue

            # Calculate vectors ab and ac
            vec_ab = [points[b][i] - point_a[i] for i in range(5)]
            vec_ac = [points[c][i] - point_a[i] for i in range(5)]

            # Check if the dot product is positive
            if dot_product(vec_ab, vec_ac) > 0:
                return False
    return True

n = int(input())
