for i in range(n):
    coords = list(map(int, input().split()))
    points.append(coords)

# Find all good points
good_points = []
for i in range(n):
    if is_good(i, points):
        good_points.append(i + 1)  # 1-indexed

# Output the result
print(len(good_points))
for point in good_points:
    print(point)
