for i in range(n, 0, -1):
    dp[i].add(i)
    for j in range(i + 1, n + 1):
        if a[i - 1] & a[j - 1] > 0:
            dp[i].update(dp[j])

# Process queries
for _ in range(q):
    x, y = map(int, input().split())
    print("Shi" if y in dp[x] else "Fou")
